import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ListGroup, ListGroupItem } from 'reactstrap';

const ProposalListModal = ({ isOpen, toggle, userId }) => {
    const [proposals, setProposals] = useState([]);

    useEffect(() => {
        if (isOpen) {
            fetch(`http://localhost:8080/api/proposals/byUserId/${userId}`)
                .then((response) => response.json())
                .then((data) => {
                    setProposals(data);
                })
                .catch((error) => console.error('Error:', error));
        }
    }, [isOpen, userId]);

    return (
        <Modal isOpen={isOpen} toggle={toggle} size="lg">
            <ModalHeader toggle={toggle}>제안서 목록</ModalHeader>
            <ModalBody>
                <ListGroup>
                    {proposals.map((proposal) => (
                        <ListGroupItem key={proposal.id}>{proposal.goodName}</ListGroupItem>
                    ))}
                </ListGroup>
            </ModalBody>
        </Modal>
    );
};

export default ProposalListModal;
